CREATE OR REPLACE FUNCTION pg_temp.check_true(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',label; END IF; END $$;
CREATE OR REPLACE FUNCTION pg_temp.expect_error(statement text,fragment text) RETURNS void LANGUAGE plpgsql AS $$DECLARE failed boolean:=false;BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN IF position(fragment IN SQLERRM)=0 THEN RAISE EXCEPTION 'Unexpected error: % wanted %',SQLERRM,fragment;END IF;failed:=true;END;IF NOT failed THEN RAISE EXCEPTION 'Expected rejection: %',fragment;END IF;END $$;
SET ROLE anon;
SELECT pg_temp.expect_error('SELECT public.member_google_email()','permission denied');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000093',false);
SET ROLE authenticated;
SELECT pg_temp.check_true(public.member_google_email()->>'emailVerified'='false','auto-confirm and metadata do not prove Google email');
SELECT pg_temp.expect_error($q$INSERT INTO auth.identities(user_id,provider,identity_data) VALUES('00000000-0000-4000-8000-000000000093','google','{"email_verified":true}')$q$,'permission denied');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000094',false);
SET ROLE authenticated;
SELECT pg_temp.check_true(public.member_google_email()->>'emailVerified'='false','unverified Google claim rejected');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000092',false);
SET ROLE authenticated;
SELECT pg_temp.check_true(public.member_google_email()->>'emailVerified'='true','trusted provider identity accepted');
SELECT pg_temp.check_true(public.member_identity()->>'emailVerified'='true','proof integrates with existing identity status');
SELECT pg_temp.check_true(public.member_identity()->>'canInteract'='false','email alone never replaces phone proof');
RESET ROLE;
UPDATE public.member_identity_verifications SET phone_number='+5511999999999',phone_verified_at=now() WHERE user_id='00000000-0000-4000-8000-000000000092';
SELECT pg_temp.check_true(public.member_identity_verified('00000000-0000-4000-8000-000000000092'),'verified email and phone unlock existing gate');
UPDATE auth.users SET email='changed@example.invalid' WHERE id='00000000-0000-4000-8000-000000000092';
SET ROLE authenticated;
SELECT pg_temp.check_true(public.member_google_email()->>'emailVerified'='false','old provider email cannot prove changed mailbox');
SELECT pg_temp.check_true(public.member_identity()->>'emailVerified'='false','existing proof does not cover different email');
RESET ROLE;
UPDATE auth.users SET email='google@example.invalid',email_confirmed_at=NULL WHERE id='00000000-0000-4000-8000-000000000092';
SET ROLE authenticated;
SELECT pg_temp.check_true(public.member_google_email()->>'emailVerified'='false','Auth must independently confirm address');
RESET ROLE;
UPDATE public.member_profiles SET suspended=true WHERE user_id='00000000-0000-4000-8000-000000000092';
SET ROLE authenticated;
SELECT pg_temp.expect_error('SELECT public.member_google_email()','community_join_required');
RESET ROLE;
SELECT pg_temp.check_true(NOT EXISTS(SELECT 1 FROM public.editorial_admin_memberships WHERE user_id='00000000-0000-4000-8000-000000000092'),'Google sign-in never grants Admin');

-- Protect automatic linking to an immediate-access password signup.
UPDATE auth.users SET encrypted_password='synthetic-hash-not-a-password' WHERE id='00000000-0000-4000-8000-000000000093';
SELECT pg_temp.expect_error($q$INSERT INTO auth.identities(user_id,provider,identity_data) VALUES('00000000-0000-4000-8000-000000000093','google','{"email":"fake@example.invalid","email_verified":true}')$q$,'google_link_requires_verified_email');
INSERT INTO public.member_identity_verifications(user_id,email_address,email_verified_at) VALUES('00000000-0000-4000-8000-000000000093','fake@example.invalid',now());
INSERT INTO auth.identities(user_id,provider,identity_data) VALUES('00000000-0000-4000-8000-000000000093','google','{"email":"fake@example.invalid","email_verified":true}');
SELECT pg_temp.check_true(EXISTS(SELECT 1 FROM auth.identities WHERE user_id='00000000-0000-4000-8000-000000000093' AND provider='google'),'verified existing password account may link Google');
UPDATE public.member_identity_verifications SET email_address='stale@example.invalid' WHERE user_id='00000000-0000-4000-8000-000000000093';
SELECT pg_temp.expect_error($q$UPDATE auth.identities SET identity_data='{"email":"fake@example.invalid","email_verified":true}' WHERE user_id='00000000-0000-4000-8000-000000000093' AND provider='google'$q$,'google_link_requires_verified_email');
